// Go vanity import path server.
//
// The go command resolves an import path such as go.example.com/foo/bar by
// fetching https://go.example.com/foo/bar?go-get=1 and reading the go-import
// meta tag, which names the import root and the repository behind it
// (https://go.dev/ref/mod#vcs-find). Browsers are redirected instead.
//
// VANITY_CONFIG is a JSON binding generated by the OpenTofu module:
//
//   {
//     "redirect_status": 302,
//     "hosts": {
//       "go.example.com": {
//         "index": "https://github.com/example",       // or null
//         "roots": {
//           "foo": {
//             "vcs": "git",
//             "repository": "https://github.com/example/foo",
//             "redirect": "https://github.com/example/foo", // or null
//             "source": null  // or { "home", "directory", "file" }
//           }
//         }
//       }
//     }
//   }
//
// Root keys are paths below the host without surrounding slashes; "" makes
// the host itself an import root. A null redirect sends browsers to the
// requested path on pkg.go.dev.

export default {
  fetch(request, env) {
    return handle(request, env.VANITY_CONFIG);
  },
};

export function handle(request, config) {
  const url = new URL(request.url);
  const host = lookup(config.hosts, url.hostname);
  if (!host) return notFound();

  const path = url.pathname.replace(/^\/+|\/+$/g, "");
  const match = findRoot(host.roots, path);

  if (url.searchParams.get("go-get") === "1") {
    return match ? goImport(url.hostname, match.path, match.root) : notFound();
  }
  if (match) {
    const target = match.root.redirect ?? `https://pkg.go.dev/${join(url.hostname, path)}`;
    return Response.redirect(target, config.redirect_status);
  }
  if (path === "" && host.index) {
    return Response.redirect(host.index, config.redirect_status);
  }
  return notFound();
}

// findRoot returns the root whose path is the longest prefix of path, matching
// whole segments only, so root "foo" serves "foo/bar" but not "foobar".
function findRoot(roots, path) {
  let candidate = path;
  for (;;) {
    const root = lookup(roots, candidate);
    if (root) return { path: candidate, root };
    if (candidate === "") return null;
    const slash = candidate.lastIndexOf("/");
    candidate = slash === -1 ? "" : candidate.slice(0, slash);
  }
}

function goImport(hostname, rootPath, root) {
  const prefix = join(hostname, rootPath);
  const tags = [meta("go-import", `${prefix} ${root.vcs} ${root.repository}`)];
  if (root.source) {
    const { home, directory, file } = root.source;
    tags.push(meta("go-source", `${prefix} ${home} ${directory} ${file}`));
  }
  const body = `<!DOCTYPE html>\n<html>\n<head>\n${tags.join("\n")}\n</head>\n</html>\n`;
  return new Response(body, {
    headers: { "content-type": "text/html; charset=utf-8" },
  });
}

function meta(name, content) {
  return `<meta name="${name}" content="${escapeHTML(content)}">`;
}

function escapeHTML(s) {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

function join(hostname, path) {
  return path === "" ? hostname : `${hostname}/${path}`;
}

// lookup reads own properties only, so paths like "/constructor" don't match
// inherited object properties.
function lookup(object, key) {
  return Object.hasOwn(object, key) ? object[key] : undefined;
}

function notFound() {
  return new Response("Not Found\n", {
    status: 404,
    headers: { "content-type": "text/plain; charset=utf-8" },
  });
}
